use crate::model::Summary;

fn checksum(payload: &[u8]) -> u8 {
    payload
        .iter()
        .fold(0u8, |sum, byte| sum.wrapping_add(*byte))
}

pub fn run(data: &[u8], limit: i64) -> Summary {
    let mut frames = Vec::new();
    let mut cursor = 0usize;
    let mut error = 0i64;

    while cursor < data.len() {
        let start = cursor;
        let marker = data[cursor];

        if marker == 255 {
            cursor += 1;
            continue;
        }

        let (length, payload_start) = if marker == 254 {
            if data.len() - cursor < 3 {
                error = 1;
                break;
            }
            let length = i64::from(data[cursor + 1])
                | (i64::from(data[cursor + 2]) << 8);
            (length, cursor + 3)
        } else {
            (i64::from(marker), cursor + 1)
        };

        if length > limit {
            error = 3;
            break;
        }

        let payload_length = length as usize;
        if data.len() - payload_start < payload_length + 1 {
            error = 1;
            break;
        }

        let checksum_index = payload_start + payload_length;
        let payload = &data[payload_start..checksum_index];
        if checksum(payload) != data[checksum_index] {
            error = 2;
            break;
        }

        frames.push(payload.to_vec());
        cursor = checksum_index + 1;
        debug_assert!(cursor > start);
    }

    Summary {
        frames,
        consumed: if error == 0 { data.len() as i64 } else { cursor as i64 },
        error,
    }
}

